import '../config/app_config.dart'; import '../config/supabase_config.dart';
class ModerationRepository { final c=SupabaseConfig.client; Future<void>block(String id)async{if(!AppConfig.demoMode)await c.rpc('block_user',params:{'p_user_id':id});} Future<void>unblock(String id)async{if(!AppConfig.demoMode)await c.rpc('unblock_user',params:{'p_user_id':id});} Future<bool>blocked(String id)async{if(AppConfig.demoMode)return false;return await c.rpc('is_user_blocked',params:{'p_user_id':id}) as bool;} Future<void>report({String?userId,String?partyId,String?mediaId,String?commentId,required String reason,String?description})async{if(!AppConfig.demoMode)await c.rpc('create_report',params:{'p_reported_user_id':userId,'p_party_id':partyId,'p_media_id':mediaId,'p_comment_id':commentId,'p_reason':reason,'p_description':description});}}
